import{_ as a,c as r,o as t,ag as o}from"./chunks/framework.C86mscM5.js";const i="/fe-handbook/assets/20200705231521653.DDwKviAW.png",n="/fe-handbook/assets/architure.mjz886BE.png",s="/fe-handbook/assets/8c3d493baf09498a8e4b865cbb9ea0a7.BlRtrkEh.png",_=JSON.parse('{"title":"Docker Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"devops/containers/docker/architecture.md","filePath":"devops/containers/docker/architecture.md","lastUpdated":1788689791000}'),c={name:"devops/containers/docker/architecture.md"};function l(d,e,h,p,u,m){return t(),r("div",null,e[0]||(e[0]=[o('<h1 id="docker-architecture" tabindex="-1">Docker Architecture <a class="header-anchor" href="#docker-architecture" aria-label="Permalink to &quot;Docker Architecture&quot;">​</a></h1><p><img src="'+i+'" alt="20200705231521653.png"></p><p><img src="'+n+'" alt="Untitled"></p><p><img src="'+s+'" alt="8c3d493baf09498a8e4b865cbb9ea0a7.png"></p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li>镜像(Image)：软件打包好的镜像</li><li>容器(Container)：镜像启动后的实例称为一个容器；容器是独立运行的一个或一组应用</li><li>仓库(Registry)：用来保存各种打包好的软件镜像</li><li>一个容器就是一个独立的虚拟操作系统，互不影响，而镜像就是这个操作系统的安装包</li><li>类似面向对象程序设计中的类和实例，镜像是静态的定义，容器是镜像运行时的实体</li><li>镜像本身是可读的，启动镜像时，Docker会在镜像的最上一层创建一个可写层</li></ul><h3 id="images" tabindex="-1"><a href="https://docs.docker.com/get-started/overview/#images" target="_blank" rel="nofollow noopener noreferrer"><strong>Images</strong></a> <a class="header-anchor" href="#images" aria-label="Permalink to &quot;[**Images**](https://docs.docker.com/get-started/overview/#images)&quot;">​</a></h3><p>An image is a read-only template with instructions for creating a Docker container.</p><h3 id="containers" tabindex="-1"><a href="https://docs.docker.com/get-started/overview/#containers" target="_blank" rel="nofollow noopener noreferrer"><strong>Containers</strong></a> <a class="header-anchor" href="#containers" aria-label="Permalink to &quot;[**Containers**](https://docs.docker.com/get-started/overview/#containers)&quot;">​</a></h3><p>A container is a runnable instance of an image.</p><h2 id="镜像的命名规则" tabindex="-1">镜像的命名规则 <a class="header-anchor" href="#镜像的命名规则" aria-label="Permalink to &quot;镜像的命名规则&quot;">​</a></h2><ul><li>镜像名包括命名空间和仓库名</li><li>标签用于区分不同版本的镜像</li></ul><h2 id="容器的状态" tabindex="-1">容器的状态 <a class="header-anchor" href="#容器的状态" aria-label="Permalink to &quot;容器的状态&quot;">​</a></h2><ul><li>已创建（created）、重启中（restarting）、运行中（running）、已暂停（paused）和已退出（exited）</li><li>容器可以被创建、启动、运行、停止、删除、暂停</li></ul>',14)]))}const k=a(c,[["render",l]]);export{_ as __pageData,k as default};
